from pathlib import Path
import json,hashlib,shutil
import numpy as np
from prepare import O,R,PERIODS,MODELS

def main():
 assert (O/'evaluation_complete.json').exists()
 nodes=json.loads((O/'data/nodes.json').read_text());source=json.loads((O/'data/source_progress_17.json').read_text());confirmed={h['label']:h for h in source['root_structure_annotation']['root_track_hierarchy'] if h.get('annotation_status_v60')=='user_defined'};allh={h['root_id']:h for h in source['root_structure_annotation']['root_track_hierarchy']};family={label:allh[h['family_root_id']]['label'] for label,h in confirmed.items()};catalog=json.loads((R/'results/B3_annotation_restore_v50_20261025/remote_image_catalogue.json').read_text());images={t:next(c['url'] for c in catalog if c['name']==t+'_RGB.png') for t in PERIODS};names={};conflicts={}
 for m in MODELS:
  reg=json.loads((O/(m+'_gat')/'track_registry.json').read_text());tracks=np.load(O/(m+'_gat')/'node_track.npy');names[m]=[reg[int(c)]['display_label'] for c in tracks];conflicts[m]=[reg[int(c)]['seed_label_conflict'] for c in tracks]
 first={(n['period'],n['segment_id']):n['node'] for n in reversed(nodes)};records=[];record_ids=[]
 for ti,f in enumerate(source['root_structure_annotation']['periods']):
  for seg in f['segments']:
   nid=first[f['period'],seg['id']];records.append(dict(t=ti,p=seg['points'],h=nodes[nid]['manual_label']));record_ids.append(nid)
 names={m:[v[i] for i in record_ids] for m,v in names.items()};conflicts={m:[v[i] for i in record_ids] for m,v in conflicts.items()}
 data=dict(images=images,families=family,nodes=records,names=names,conflicts=conflicts)
 html=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>人工根号与GAT跟踪对照 V65</title><style>
 body{margin:16px;font:15px Arial,sans-serif;color:#111;background:#fff}h1{font-size:23px}button,input,select{font-size:15px;margin:4px;padding:6px}.toolbar{position:sticky;top:0;background:#fff;padding:8px;z-index:4;border:1px solid #bbb}#panes{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:10px}.card{border:1px solid #aeb7bf;border-radius:5px;padding:6px;min-width:0}.card h2{font-size:18px;margin:4px}.scroll{height:410px;overflow:auto;background:#ddd;cursor:grab}.scroll:active{cursor:grabbing}svg{display:block;background:#fff}.note{line-height:1.6;max-width:1300px}#status{margin:5px 0;font-weight:bold}svg text{fill:#000;font-weight:bold;pointer-events:none}svg rect{fill:white;stroke:#444;stroke-width:1;vector-effect:non-scaling-stroke}svg path{cursor:pointer;fill:none;stroke-linecap:round} @media(max-width:900px){#panes{grid-template-columns:1fr}}</style>
<h1>四期人工根系编号与三个 GAT 跟踪结果</h1><p class="note">人工编号来自上传 (17).json 中已确认的142条根；未确认的12条补标不作为真值。模型学习同根、母侧根及不同根的关联。预测的文字编号由根首次出现时的人工名称锚定；后续时期由模型关联，首次出现的锚定不计为预测成功。这里显示中心线编号示意，不能用于测量根宽；原标注未被覆盖。</p>
<div class="toolbar"><span id="periods"></span><label>缩放 <input id="zoom" type="range" min="0.3" max="5" value="0.5" step="0.1"></label><label>查编号 <input id="search" placeholder="例如 0001、0001-2、N-0026"></label><label><input id="family" type="checkbox">含侧根家族</label><label><input id="unknown" type="checkbox">显示未命名预测编号</label><button id="reset">全图／清除筛选</button><div id="status"></div></div><div id="panes"></div>
<p class="note">拖动或滚动任意画面，四个面板同步；点击根线可按编号筛选。灰线表示尚未锚定名称的轨迹；P-xxxx 是模型内部跟踪号，不代表确认的新生根。* 表示同一预测轨迹含有多个首次标注锚点，需要检查误并。三类时序性能与编号一致性为单个B3视野的内部结果，不代表外部泛化。</p>
<script id="data" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('data').textContent),svgNS='http://www.w3.org/2000/svg',keys=['human','unet','deeplab','segformer'],titles=['人工编号参考','U-Net + GAT','DeepLabV3+ + GAT','SegFormer-B0 + GAT'];let period=0,zoom=.5,syncing=false;const panels=[];const $=id=>document.getElementById(id);function element(tag,attrs){const e=document.createElementNS(svgNS,tag);for(const[k,v]of Object.entries(attrs||{}))e.setAttribute(k,v);return e;}
function color(label){if(!label||label.startsWith('P-'))return '#b2b8bd';const family=data.families[label]||label;let h=0;for(const c of family)h=(h*31+c.charCodeAt(0))>>>0;return `hsl(${h*137.508%360},78%,48%)`;}
for(let i=0;i<4;i++){const b=document.createElement('button');b.textContent='T'+(i+1);b.dataset.period=i;b.onclick=()=>{period=i;render()};$('periods').append(b);}
for(let i=0;i<4;i++){const card=document.createElement('section');card.className='card';const h=document.createElement('h2');h.textContent=titles[i];card.append(h);const box=document.createElement('div');box.className='scroll';const svg=element('svg');box.append(svg);card.append(box);$('panes').append(card);panels.push({box,svg,key:keys[i]});box.onscroll=()=>{if(syncing)return;syncing=true;for(const p of panels)if(p.box!==box){p.box.scrollLeft=box.scrollLeft;p.box.scrollTop=box.scrollTop;}syncing=false;};let drag=null;box.onpointerdown=e=>{if(e.button)return;drag={x:e.clientX,y:e.clientY,left:box.scrollLeft,top:box.scrollTop,moved:false,label:e.target.dataset.label||''};box.setPointerCapture(e.pointerId)};box.onpointermove=e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>4)drag.moved=true;box.scrollLeft=drag.left-(e.clientX-drag.x);box.scrollTop=drag.top-(e.clientY-drag.y)};box.onpointerup=e=>{if(drag&&!drag.moved&&drag.label){$('search').value=drag.label;render();}drag=null};box.onpointercancel=()=>drag=null;}
function matches(label,query){return !query||label===query||($('family').checked&&label&&label.startsWith(query+'-'));}
function render(){const query=$('search').value.trim().toUpperCase();for(const b of $('periods').children)b.style.fontWeight=Number(b.dataset.period)===period?'bold':'normal';for(const panel of panels){const svg=panel.svg;svg.replaceChildren();svg.setAttribute('viewBox','0 0 2541 1108');svg.setAttribute('width',2541*zoom);svg.setAttribute('height',1108*zoom);svg.append(element('image',{href:data.images['T'+(period+1)],x:0,y:0,width:2541,height:1108}));const groups=new Map();for(let i=0;i<data.nodes.length;i++){const n=data.nodes[i];if(n.t!==period)continue;const label=panel.key==='human'?n.h:data.names[panel.key][i];const known=!!label&&!label.startsWith('P-');if(query&&!matches(label,query))continue;const path=element('path',{d:n.p.map((p,j)=>(j?'L':'M')+p.join(',')).join(' '),stroke:color(label),'stroke-width':(known?1.9:1.1)/zoom,opacity:known?1:.35});path.dataset.label=label||'';svg.append(path);if(label&&(known||$('unknown').checked)){if(!groups.has(label))groups.set(label,[]);groups.get(label).push({node:n,index:i});}}
 const occupied=[];for(const[label,rows]of groups){let best=rows.reduce((a,b)=>a.node.p.length>b.node.p.length?a:b),p=best.node.p[Math.floor(best.node.p.length/2)],conflict=panel.key==='human'?false:data.conflicts[panel.key][best.index];const labelText=label+(conflict?'*':'');const w=(labelText.length*8+10)/zoom,h=20/zoom,x=Math.max(1,Math.min(2541-w-1,p[0]+4/zoom)),y=Math.max(1,Math.min(1108-h-1,p[1]-h));if(!query&&occupied.some(b=>x<b[0]+b[2]&&x+w>b[0]&&y<b[1]+b[3]&&y+h>b[1]))continue;occupied.push([x,y,w,h]);const g=element('g');g.append(element('rect',{x,y,width:w,height:h,rx:2/zoom}));const text=element('text',{x:x+4/zoom,y:y+15/zoom,'font-size':14/zoom});text.textContent=labelText;g.append(text);svg.append(g);}}
 $('status').textContent='T'+(period+1)+' · 缩放 '+zoom.toFixed(1)+'× · '+(query?'筛选 '+query:'全部编号；重叠文字会略去，放大或查编号可查看');}
$('zoom').oninput=()=>{zoom=Number($('zoom').value);render()};$('search').oninput=render;$('family').onchange=render;$('unknown').onchange=render;$('reset').onclick=()=>{$('search').value='';$('family').checked=false;zoom=.5;$('zoom').value=zoom;render();for(const p of panels){p.box.scrollLeft=0;p.box.scrollTop=0;}};render();window.viewerReady65={panels:4,confirmed_roots:Object.keys(data.families).length};
</script></html>'''
 html=html.replace('__DATA__',json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/'));(O/'Root_ID_comparison.html').write_text(html)
 test=html;(O/'viewer-assets').mkdir(exist_ok=True)
 for t in PERIODS:
  source=R/f'results/B3_temporal_initialization_v43_20261024/data/upper/{t}_RGB.png';dest=O/'viewer-assets'/(t+'_RGB.png')
  if not dest.exists():dest.symlink_to(source)
  test=test.replace(images[t],'http://127.0.0.1:8894/viewer-assets/'+t+'_RGB.png')
 (O/'viewer_test.html').write_text(test);print('VIEWER_WRITTEN',len(html.encode()),flush=True)
if __name__=='__main__':main()
